import itertools
import json

def minutes(h, m=0):
    return h * 60 + m

def parse_time_24(h, m):
    return minutes(h, m)

def fmt_time(total_minutes):
    h = total_minutes // 60
    m = total_minutes % 60
    return f"{h}:{m:02d}"

def schedule_for_order(order, people, travel, start_loc, start_time):
    time = start_time
    loc = start_loc
    itinerary = []
    total_travel = 0
    for name in order:
        p = people[name]
        if loc not in travel or p["location"] not in travel[loc]:
            return None
        t_travel = travel[loc][p["location"]]
        total_travel += t_travel
        arrival = time + t_travel
        start = max(arrival, p["start"])
        end = start + p["min_dur"]
        if end > p["end"]:
            return None
        itinerary.append({
            "action": "meet",
            "location": p["location"],
            "person": name,
            "start_time": fmt_time(start),
            "end_time": fmt_time(end)
        })
        time = end
        loc = p["location"]
    return {
        "itinerary": itinerary,
        "end_time": time,
        "total_travel": total_travel,
        "met_count": len(order)
    }

def find_best_schedule(people, travel, start_loc, start_time):
    names = list(people.keys())
    best = None
    # Try to meet as many as possible: start from all, go down if needed
    for k in range(len(names), 0, -1):
        best_for_k = None
        for order in itertools.permutations(names, k):
            res = schedule_for_order(order, people, travel, start_loc, start_time)
            if res is None:
                continue
            if best_for_k is None:
                best_for_k = res
            else:
                # Prefer earliest end_time, then minimal total_travel
                if (res["end_time"], res["total_travel"]) < (best_for_k["end_time"], best_for_k["total_travel"]):
                    best_for_k = res
        if best_for_k is not None:
            best = best_for_k
            break
    return best

